package com.bank.dns;

import java.util.*;
import java.util.logging.*;

public class Route53Demo {
    private static final Logger log = Logger.getLogger("Route53");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        HealthCheck mumbaiHealth = new HealthCheck(true);
        DnsRecord primary = new DnsRecord("mumbai.bank.example.com", "PRIMARY", mumbaiHealth);
        DnsRecord secondary = new DnsRecord("singapore.bank.example.com", "SECONDARY", new HealthCheck(true));

        Route53Resolver resolver = new Route53Resolver(primary, secondary);

        log.info(() -> "Query 1 (Mumbai healthy): resolves to " + resolver.resolveFailover());

        mumbaiHealth.setHealthy(false);
        log.warning(() -> "Health check: mumbai.bank.example.com reported UNHEALTHY");
        log.info(() -> "Query 2 (Mumbai down): resolves to " + resolver.resolveFailover());
    }
}

// ─── Would be in Route53Resolver.java ───
class Route53Resolver {
    private final DnsRecord primary;
    private final DnsRecord secondary;
    Route53Resolver(DnsRecord primary, DnsRecord secondary) {
        this.primary = primary; this.secondary = secondary;
    }

    // Failover policy: return primary while healthy, else the secondary.
    String resolveFailover() {
        return primary.healthCheck().isHealthy() ? primary.endpoint() : secondary.endpoint();
    }
}

// ─── Would be in DnsRecord.java ───
class DnsRecord {
    private final String endpoint;
    private final String role;
    private final HealthCheck healthCheck;
    DnsRecord(String endpoint, String role, HealthCheck healthCheck) {
            this.endpoint = endpoint;
            this.role = role
            this.healthCheck = healthCheck;
    }
    String endpoint() { return endpoint; }
    String role() { return role; }
    HealthCheck healthCheck() { return healthCheck; }
}

// ─── Would be in HealthCheck.java ───
class HealthCheck {
    private volatile boolean healthy;
    HealthCheck(boolean healthy) { this.healthy = healthy; }
    boolean isHealthy() { return healthy; }
    void setHealthy(boolean healthy) { this.healthy = healthy; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
